async function enableNotifications(){if(S.settings.reminders){S.settings.reminders=false;persist();render();toast('Rappels ouverts desactives. Les evenements externes sont inchanges.');return;}if(!('Notification'in window)||!isSecureContext){toast('Notifications non disponibles ici. Utilise le rappel du calendrier.',true);return;}try{const permission=await Notification.requestPermission();S.settings.reminders=permission==='granted';persist();render();toast(S.settings.reminders?'Rappels actives tant que l\'application reste ouverte.':'Permission non accordee. Le calendrier reste disponible.');}catch{toast('Notifications indisponibles sur ce navigateur. Utilise le calendrier.',true);}}
async function checkReminders(){if(!S.settings.reminders)return;const now=Date.now();for(const e of S.events){if(!e.reminder||e.lastNotified||notified.has(e.id))continue;let start;try{start=+KQ.zonedDate(e.date,e.time,S.settings.timeZone);}catch{continue;}if(start-now>=-120000&&start-now<=900000){notified.add(e.id);e.lastNotified=Date.now();persist();toast('Rendez-vous Knee Quest a '+e.time+'. Tu peux le deplacer si besoin.');if('Notification'in window&&Notification.permission==='granted'){try{new Notification('Knee Quest',{body:'Ton rendez-vous est prevu a '+e.time+'. Ouvre ton planning.',tag:e.id});}catch{try{const reg=await navigator.serviceWorker?.getRegistration();if(reg)await reg.showNotification('Knee Quest',{body:'Ton rendez-vous est prevu a '+e.time+'.',tag:e.id});}catch{}}}}}}
let wakeLock=null;async function requestWakeLock(){try{if(navigator.wakeLock&&document.visibilityState==='visible')wakeLock=await navigator.wakeLock.request('screen');}catch{}}
function releaseWakeLock(){try{wakeLock?.release();wakeLock=null;}catch{}}
/* Included inside app.js so the legacy timers, editing and games share one state. */
function familyColor(g){return ({quadriceps:'#64c7ff',fessiers:'#ffa8ce',ischios:'#b9a0ff',adducteurs:'#f5ac76',abducteurs:'#5cdec5',mollets:'#b3e277',soleaire:'#b3e277',polyarticulaire:'#a0b5ff',proprioception:'#61e0f3',tronc:'#eab9ff',obliques:'#eab9ff',poussee:'#ffb08b',biceps:'#ffb08b',triceps:'#ffb08b','stabilite-jambe':'#87dfb0','stabilite-hanche':'#87dfb0'})[g]||'#9ab7cf';}
